//! Raw bindings to `slimedisplay.h` / `slimedisplay_types.h`.
//!
//! With the `bindgen` feature these are generated by `build.rs`. Otherwise the
//! hand-maintained copy below is used, and it MUST be kept in sync with the
//! C headers (README §11.6).

#![allow(non_camel_case_types, non_upper_case_globals, non_snake_case, dead_code)]

#[cfg(feature = "bindgen")]
include!(concat!(env!("OUT_DIR"), "/slimedisplay_bindings.rs"));

#[cfg(not(feature = "bindgen"))]
pub use manual::*;

#[cfg(not(feature = "bindgen"))]
mod manual {
    use std::os::raw::{c_int, c_void};

    /// Opaque backend handle. Never dereferenced from Rust.
    #[repr(C)]
    pub struct SD_Handle {
        _unused: [u8; 0],
    }

    pub type SD_Result = c_int;
    pub const SD_SUCCESS: SD_Result = 0;
    pub const SD_ERROR_INVALID_ARGUMENT: SD_Result = -1;
    pub const SD_ERROR_INITIALIZATION: SD_Result = -2;
    pub const SD_ERROR_NOT_SUPPORTED: SD_Result = -3;
    pub const SD_ERROR_PERMISSION_DENIED: SD_Result = -4;
    pub const SD_ERROR_CAPTURE: SD_Result = -5;
    pub const SD_ERROR_ENCODING: SD_Result = -6;
    pub const SD_ERROR_TRANSPORT: SD_Result = -7;
    pub const SD_ERROR_INVALID_STATE: SD_Result = -8;
    pub const SD_ERROR_INTERNAL: SD_Result = -9;

    #[repr(C)]
    #[derive(Debug, Copy, Clone)]
    pub struct SD_DisplayConfig {
        pub width: u32,
        pub height: u32,
        pub fps: u32,
    }

    #[repr(C)]
    #[derive(Debug, Copy, Clone)]
    pub struct SD_DisplayInfo {
        pub id: u64,
        pub width: u32,
        pub height: u32,
        pub refresh_rate: u32,
    }

    // A C enum with only non-negative values is `unsigned int` on clang and `int` on MSVC.
    #[cfg(windows)]
    pub type SD_PixelFormat = c_int;
    #[cfg(not(windows))]
    pub type SD_PixelFormat = std::os::raw::c_uint;
    pub const SD_PIXEL_FORMAT_UNKNOWN: SD_PixelFormat = 0;
    pub const SD_PIXEL_FORMAT_BGRA: SD_PixelFormat = 1;
    pub const SD_PIXEL_FORMAT_NV12: SD_PixelFormat = 2;
    pub const SD_PIXEL_FORMAT_I420: SD_PixelFormat = 3;

    #[repr(C)]
    #[derive(Debug, Copy, Clone)]
    pub struct SD_FrameInfo {
        pub width: u32,
        pub height: u32,
        pub fps: u32,
        pub format: SD_PixelFormat,
        pub timestamp: u64,
    }

    pub type SD_EncodedFrameCallback = Option<
        unsafe extern "C" fn(
            data: *const u8,
            size: u32,
            presentation_time: i64,
            is_keyframe: i32,
            user_data: *mut c_void,
        ),
    >;

    extern "C" {
        pub fn sd_create(handle: *mut *mut SD_Handle) -> SD_Result;
        pub fn sd_destroy(handle: *mut SD_Handle);

        pub fn sd_create_virtual_display(
            handle: *mut SD_Handle,
            config: *const SD_DisplayConfig,
        ) -> SD_Result;
        pub fn sd_destroy_virtual_display(handle: *mut SD_Handle) -> SD_Result;
        pub fn sd_get_virtual_display_info(
            handle: *mut SD_Handle,
            info: *mut SD_DisplayInfo,
        ) -> SD_Result;

        pub fn sd_start_capture(handle: *mut SD_Handle) -> SD_Result;
        pub fn sd_stop_capture(handle: *mut SD_Handle) -> SD_Result;

        pub fn sd_start_encoder(handle: *mut SD_Handle) -> SD_Result;
        pub fn sd_stop_encoder(handle: *mut SD_Handle) -> SD_Result;

        pub fn sd_get_version() -> u32;

        pub fn sd_set_encoded_frame_callback(
            handle: *mut SD_Handle,
            callback: SD_EncodedFrameCallback,
            user_data: *mut c_void,
        ) -> SD_Result;
    }
}
